// Authored collision-aware labels, TacticalScene.layout_labels/ease_labels.
#include "tactical_motion_internal.hpp"
#include "tactical_frames.hpp"
#include <algorithm>
#include <cmath>
namespace transartica::panels {
namespace {
SDL_FRect grow(SDL_FRect r,double d){return{r.x-float(d),r.y-float(d),r.w+float(2*d),r.h+float(2*d)};}
double intersection(SDL_FRect a,SDL_FRect b){return std::max(0.f,std::min(a.x+a.w,b.x+b.w)-std::max(a.x,b.x))*std::max(0.f,std::min(a.y+a.h,b.y+b.h)-std::max(a.y,b.y));}
Point toward(Point a,Point b,double delta){const double d=distance(a,b);return d<=delta||d==0?b:a+(b-a)*(delta/d);}
}
void TacticalMotion::ease_labels(TacticalScreen&scene,const combat::Tactical&battle){impl_->labels(scene,battle,true);}
std::vector<TacticalMotion::Impl::Label>TacticalMotion::Impl::labels(TacticalScreen&scene,const combat::Tactical&battle,bool ease){const auto&state=battle.snapshot();std::vector<SDL_FRect>avoid;
    auto label_rect=[&](Point p,const std::string&text,int size,double anchor){const auto f=scene.frame();const double scale=f.w/320;const int pixels=std::max(1,int(std::round(size*scale)));const double width=scene.canvas_.measure(text,pixels).x/scale;return SDL_FRect{float(p.x-1-anchor*width),float(p.y-size-1),float(width+2),float(size+3)};};
    // Source wagon tags and bodies are always obstacles, including either hull.
    for(int side=0;side<2;++side){int source=0;for(int index=0;index<int(state.trains[side].size());++index){const auto&car=state.trains[side][index];if(car.kind==combat::Companion)continue;const auto g=scene.wagon(battle,side,index);const double roof=scene.surface_y(g,g.box.x+g.box.w/2);avoid.push_back({g.box.x,float(roof),g.box.w,g.box.y+g.box.h-float(roof)});if(side==0){++source;avoid.push_back(label_rect({g.box.x+2,32},std::to_string(source)+":"+std::to_string(car.health),4,0));}}}
    for(const auto&[id,t]:tracks)for(const auto&s:t->soldiers){if(s.board&&s.board->t<0)continue;const auto at=point(scene,battle,*t,s);const double facing=s.face!=0?s.face:t->facing;if(t->actor.mammoth){const int seated=t->actor.count+waiting(*t);int dying=0;for(int uid:t->dying)for(const auto&b:bodies)if(b.uid==uid&&b.t<b.delay+b.span)dying=3;const int variant=seated+dying<=1?0:t->actor.side==0?1:2;int motion=1,index=0;if(s.recoil>0){motion=3;index=s.recoil>s.recoil_len*.5?0:1;}else if(s.strike>0){motion=2;index=std::min(3,int((1-s.strike/s.strike_len)*4));}else if(s.gait>=0){motion=0;index=s.gait;}else if(s.halt>0)index=.7-s.halt>=.15?1:0;const auto&f=art::mammoth_body[variant][motion][index];const double lo=-f.pivot.x/4,hi=(f.crop.w-f.pivot.x)/4;avoid.push_back({float(at.x+std::min(lo*facing,hi*facing)),float(at.y-f.pivot.y/4),f.crop.w/4.f,f.crop.h/4.f});}
        else if(!s.board&&s.plant>=0){const auto&f=art::trooper_poses[1][t->actor.side][s.plant];const double lo=-f.pivot.x/4,hi=(f.crop.w-f.pivot.x)/4;avoid.push_back({float(at.x+std::min(lo*facing,hi*facing)),float(at.y-f.pivot.y/4),f.crop.w/4.f,f.crop.h/4.f});}else avoid.push_back({float(at.x)-4,float(at.y)-13,8,12});}
    auto cover=[&](Point p,const std::string&text,int size,double anchor,const std::vector<SDL_FRect>&obstacles){const auto raw=label_rect(p,text,size,anchor),r=grow(raw,.75);double covered=raw.x>=0&&raw.y>=22&&raw.x+raw.w<=320&&raw.y+raw.h<=200?0:1000;for(const auto&other:obstacles)covered+=intersection(r,other);return covered;};
    const auto base_obstacles=avoid;std::vector<Label>result;
    auto settle=[&](std::string key,Point home,std::string text,const std::vector<Spot>&options){Spot spot=options.front();bool kept_clear=false;if(auto old=kept.find(key);old!=kept.end()){const auto&s=old->second;if(cover(home+s.offset,text,s.size,s.anchor,avoid)==0){spot=s;kept_clear=true;}}if(!kept_clear){double least=INFINITY;for(const auto&option:options){const double covered=cover(home+option.offset,text,option.size,option.anchor,avoid);if(covered<least){least=covered;spot=option;}if(covered==0)break;}}kept[key]=spot;avoid.push_back(label_rect(home+spot.offset,text,spot.size,spot.anchor));const auto old=shown.find(key);const auto shown_offset=old==shown.end()?spot.offset:old->second;result.push_back({std::move(key),std::move(text),home,home+spot.offset,home+shown_offset,spot.offset,spot.size,spot.anchor});};
    for(const auto&c:state.charges){const auto home=place(scene,battle,c.side,{double(c.slot),0});double planter=0;for(const auto&[id,t]:tracks)for(const auto&s:t->soldiers)if(s.plant>=0&&s.task&&s.task->key==std::pair{c.side,c.slot})planter=s.face;const bool leftfirst=planter<0;std::vector<Spot>options;for(double lift:{-9.,-16.})for(int size:{5,4})for(int turn=0;turn<2;++turn){const bool left=(turn==0)==leftfirst;options.push_back({{left?-2.:0,lift},size,left?1.:0});}settle("c"+std::to_string(c.side)+"/"+std::to_string(c.slot),home,"●"+std::to_string(c.fuse),options);}
    for(const auto&[id,a]:state.actors){auto found=tracks.find(id);if(found==tracks.end()||found->second->soldiers.empty())continue;bool hidden=true;for(const auto&s:found->second->soldiers)if(!s.board||s.board->dismount<=0||s.board->t>=s.board->dismount){hidden=false;break;}if(hidden)continue;const auto home=point(scene,battle,*found->second,found->second->soldiers[0]);std::vector<Point>offsets{{-4,4},{2,4},{-6,-4},{7,-4},{-12,-4},{13,-4},{-4,11},{2,11},{-12,11},{13,11}};for(double lift:{-16.,-22.,-28.,-34.})for(double slide:{-3.,4.,-10.,11.,-17.,18.})offsets.push_back({slide,lift});std::vector<Spot>options;for(auto off:offsets)options.push_back({off,4,off.x==-6||off.x==-12?1.:0});settle("a"+std::to_string(id),home,std::to_string(a.count),options);}
    if(ease){avoid=base_obstacles;std::map<std::string,Point>next;for(auto&label:result){const auto previous=shown.find(label.key);const Point here=previous==shown.end()?label.offset:previous->second;const std::array<Point,6>steps{{toward(here,label.offset,1),here,here+Point{0,-1},here+Point{0,1},here+Point{-1,0},here+Point{1,0}}};Point best=steps[0];double least=INFINITY;for(Point step:steps){const double cost=cover(label.base+step,label.text,label.size,label.anchor,avoid)*1000+distance(step,label.offset);if(cost<least){least=cost;best=step;}}next[label.key]=best;label.shown=label.base+best;avoid.push_back(label_rect(label.shown,label.text,label.size,label.anchor));}shown=std::move(next);}return result;
}
}
